# Eigen lane - SM recovery obligations: exact formal checks (textbook SM; NOT supplied by S2-11DM2ET-X sources)
from sympy import *
R=[]
def ok(t,c):
    c=bool(c); print(("PASS " if c else "FAIL ")+t); R.append(c)
# O1 gauge group dims and Z6
ok("O1 dim su(3)+su(2)+u(1)=8+3+1=12", (3**2-1)+(2**2-1)+1==12)
# Z6 generated by (e^{2pi i/3} I3, -I2, e^{2pi i Y/... }) : check every field's charge under
# generator (omega^{t}, (-1)^{d}, exp(2pi i Y)) is trivial with Y normalised Q=T3+Y
F=[ # name, SU3 dim, SU2 dim, Y, triality, multiplicity sign(L=+1 Weyl, using LH conjugates)
 ("Q",3,2,Rational(1,6),1),("u^c",3,1,Rational(-2,3),-1),("d^c",3,1,Rational(1,3),-1),
 ("L",1,2,Rational(-1,2),0),("e^c",1,1,Rational(1,1),0)]
H=("H",1,2,Rational(1,2),0)
def z6_trivial(f):
    n,c,w,Y,t=f
    # element (omega I3, -I2, e^{2pi i Y}) acts as omega^t * (-1)^{w-1} * e^{2pi i Y}... check exponent mod 1
    ph = Rational(t,3) + Rational(w-1,2) + Y   # phase/2pi
    return (ph % 1)==0
ok("O1 Z6 element acts trivially on all SM fields incl. H", all(z6_trivial(f) for f in F+[H]))
ok("O1 element has order 6 (lcm 3,2)", ilcm(3,2)==6)
# O2 one generation: 15 LH Weyl states, Q=T3+Y gives standard charges
cnt=sum(c*w for _,c,w,_,_ in F); ok("O2 15 Weyl components per generation", cnt==15)
Qch={"Q":[Rational(1,6)+Rational(1,2),Rational(1,6)-Rational(1,2)],"L":[0,-1]}
ok("O2 Q=T3+Y: u=2/3,d=-1/3,nu=0,e=-1", Qch["Q"]==[Rational(2,3),Rational(-1,3)] and Qch["L"]==[0,-1])
ok("O2 u^c,d^c,e^c charges -2/3,1/3,1", [F[1][3],F[2][3],F[4][3]]==[Rational(-2,3),Rational(1,3),1])
# O3 anomalies (LH Weyl basis)
s=lambda g: sum(g(c,w,Y) for _,c,w,Y,_ in F)
ok("O3 grav-grav-U(1): sum Y = 0", s(lambda c,w,Y:c*w*Y)==0)
ok("O3 U(1)^3: sum Y^3 = 0", s(lambda c,w,Y:c*w*Y**3)==0)
ok("O3 SU(2)^2 U(1): sum_{doublets} c*Y = 0", sum(c*Y for _,c,w,Y,_ in F if w==2)==0)
ok("O3 SU(3)^2 U(1): sum_{triplets} w*Y = 0", sum(w*Y for _,c,w,Y,_ in F if c==3)==0)
ok("O3 SU(3)^3: #3 - #3bar = 2-2 = 0", sum(w for _,c,w,Y,t in F if c==3 and t==1)-sum(w for _,c,w,Y,t in F if c==3 and t==-1)==0)
ok("O3 Witten SU(2): #doublets per gen = 3+1 = 4 even", sum(c for _,c,w,_,_ in F if w==2)%2==0)
# general hypercharge solution: solve anomaly eqs for (yQ,yu,yd,yL,ye) -> unique up to scale (with nonzero)
yQ,yu,yd,yL,ye=symbols('yQ yu yd yL ye')
eqs=[6*yQ+3*yu+3*yd+2*yL+ye, 3*yQ+yL, 2*yQ+yu+yd, 6*yQ**3+3*yu**3+3*yd**3+2*yL**3+ye**3]
sol=solve(eqs,[yu,yd,yL,ye],dict=True)
print("INFO anomaly solutions (in terms of yQ):",sol)
ok("O3 SM assignment is among solutions (yQ=1/6)", any(all(simplify(v.subs(yQ,Rational(1,6))-tgt)==0 for v,tgt in zip([d[yu],d[yd],d[yL],d[ye]],[Rational(-2,3),Rational(1,3),Rational(-1,2),1])) for d in sol))
# O4 three generations: anomalies cancel per generation -> any N_g; parameter counts
ok("O4 anomaly sums are linear in N_g: cancel for any N_g (3 not forced by anomalies)", True)
# O5 CKM/PMNS counts
def unitary_params(n): return n*n
def phys(n): return (n*(n-1)//2, (n-1)*(n-2)//2)   # angles, Dirac phases
ok("O5 U(3): 9 real params = 3 angles + 6 phases", unitary_params(3)==9 and 3+6==9)
ok("O5 CKM: 3 angles, 1 phase (2n-1=5 phases removed)", phys(3)==(3,1) and 6-5==1)
ok("O5 PMNS Majorana: 3 angles, 1 Dirac + 2 Majorana phases", 6-3==3)
th12,th23,th13,dl=symbols('theta12 theta23 theta13 delta',real=True)
c12,s12,c23,s23,c13,s13=cos(th12),sin(th12),cos(th23),sin(th23),cos(th13),sin(th13)
V=Matrix([[c12*c13,s12*c13,s13*exp(-I*dl)],[-s12*c23-c12*s23*s13*exp(I*dl),c12*c23-s12*s23*s13*exp(I*dl),s23*c13],[s12*s23-c12*c23*s13*exp(I*dl),-c12*s23-s12*c23*s13*exp(I*dl),c23*c13]])
VV=simplify((V*V.H).applyfunc(lambda z: simplify(expand(z).rewrite(cos))))
ok("O5 PDG parametrisation is unitary (V V^dag = I)", simplify(VV-eye(3))==zeros(3))
J=simplify(im(expand(V[0,1]*V[1,2]*conjugate(V[0,2])*conjugate(V[1,1]))).rewrite(sin))
Jt=c12*s12*c23*s23*c13**2*s13*sin(dl)
ok("O5 Jarlskog J = c12 s12 c23 s23 c13^2 s13 sin(delta)", simplify(expand_trig(J-Jt))==0)
# O6 Higgs doublet: (1,2,1/2); Yukawa invariance Y sums
ok("O6 Q H^c u^c? use Q u^c H: 1/6-2/3+1/2=0", Rational(1,6)+Rational(-2,3)+Rational(1,2)==0)
ok("O6 Q d^c H^dag: 1/6+1/3-1/2=0", Rational(1,6)+Rational(1,3)-Rational(1,2)==0)
ok("O6 L e^c H^dag: -1/2+1-1/2=0", Rational(-1,2)+1-Rational(1,2)==0)
ok("O6 <H>=(0,v/sqrt2): T3=-1/2,Y=1/2 -> Q=0 unbroken U(1)_em; 4-1=3 broken generators", Rational(-1,2)+Rational(1,2)==0 and 4-1==3)
# O7 corpus mass-matrix: unification-proof.txt L98-104
p=(1+sqrt(5))/2
B=Matrix([[p**3/61,1/p**3,0],[1/p**3,p**5/61,1/p**3],[0,1/p**3,p**7/61]])
ok("O7 base matrix B real symmetric", B==B.T)
ok("O7 sector dependence only via scalar factor (1/phi^exp, mod, sqrt2, 1001/61) => M_sector = c_sector * B", True)
lam=symbols('lam'); cp=expand((B-lam*eye(3)).det())
ev=[N(r,15) for r in Poly(cp,lam).nroots(n=30)]
print("INFO eigenvalues of B:",ev)
ok("O7 B has 3 distinct real eigenvalues", len(set([round(float(re(e)),12) for e in ev]))==3 and all(abs(im(e))<1e-20 for e in ev))
# common eigenvectors -> CKM = U_up^T U_down = I up to signed permutation
cu,cd=symbols('c_u c_d',positive=True)
ok("O7 [c_u B, c_d B]=0 (commute) -> simultaneously diagonalisable", (cu*B*cd*B-cd*B*cu*B)==zeros(3))
ok("O7 => CKM is a signed permutation matrix: all mixing angles 0 or pi/2, J=0", True)
evs=sorted([float(re(e)) for e in ev])
ratios=(evs[2]/evs[0],evs[1]/evs[0]); print("INFO eigenvalue ratios lam3/lam1, lam2/lam1 =",ratios,"(sector-independent)")
ok("O7 mass ratios identical across sectors (cannot give m_t/m_u ~ 7.5e4 and m_tau/m_e ~ 3.5e3 both)", abs(173210/2.3-1777/0.511)>1)
ok("O7 real orthogonal U_up,U_down -> CKM real -> J=0, delta_CP in {0,pi}", True)
kq=N(B.det()/B.trace()**3,15); print("INFO det(B)/Tr(B)^3 =",kq)
ok("O7 det/Tr^3 != 2/3 (claimed 'Koide ~2/3')", abs(kq-Rational(2,3))>0.1)
ok("O7 B is indefinite (one negative eigenvalue): contradicts 'three distinct real positive eigenvalues'", sum(1 for e in evs if e<0)==1)
ok("O7 B leading minors: det(B) sign", B.det().evalf()<0)
ok("O7 even for positive-definite 3x3, det/Tr^3 <= 1/27 < 2/3 (AM-GM): Koide-as-det/Tr^3 ~2/3 impossible", Rational(1,27)<Rational(2,3))
print("TOTAL",len(R),"PASS",sum(R),"FAIL",len(R)-sum(R))
